TypeScript (sketch):

export type EnvelopeType = 'delta' | 'tool' | 'structured' | 'final' | 'error'

export interface EventEnvelope {
  id?: string; // optional correlate across events
  type: EnvelopeType;
  payload?: any; // token fragments, tool args/result, partial JSON chunks
  schema?: string; // optional content schema name, e.g. 'redwood.func.call'
  trace?: { requestId?: string, generation?: number } | null;
}

Usage in streaming client:
const stream = client.stream({..., envelope: true});
for await (const evt of stream) {
  switch(evt.type) {
    case 'delta': handleToken(evt.payload); break;
    case 'tool': handleToolEvent(evt.payload); break;
    case 'structured': assembleStructured(evt.payload, evt.schema); break;
  }
}

